use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " A trait implemented for various AST nodes, providing all pieces"] # [doc = " of functionality used by `InvocationCollector`."] # [doc = ""] # [doc = " This trait acts as an adapter, allowing the `InvocationCollector` to interact with"] # [doc = " different AST node types in a generic way. Each implementor defines how it should be"] # [doc = " processed during macro invocation collection and expansion."] # [doc = ""] # [doc = " For n00bs: This is like a \"how-to guide\" for each type of code snippet (like a function,"] # [doc = " or a variable declaration). It tells the macro system:"] # [doc = " - How to get its unique ID (`HasNodeId`)."] # [doc = " - How to check for attributes (`HasAttrs`)."] # [doc = " - What kind of output it expects after a macro is expanded (`VisitOutputTy`, `FlatMapOutputTy`)."] # [doc = " - How to convert itself into a generic `Annotatable` type."] # [doc = " - How to handle attributes (`pre_flat_map_node_collect_attr`, `post_flat_map_node_collect_bang`)."] # [doc = " - How to \"walk\" its internal structure to find more macro calls (`walk`, `walk_flat_map`)."] pub trait InvocationCollectorNode : HasAttrs + HasNodeId + Sized + MacroInvocationNode < ItemKind = ast :: ItemKind > + AstFragmentConverter + WalkableAstNode < FlatMapOutputTy = < Self as AstFragmentConverter > :: FlatMapOutputTy > + CfgFalseExpandable + HasDeclaredIdents + FlattensOutputs < FlatMapOutputTy = < Self as AstFragmentConverter > :: FlatMapOutputTy > + AttributeHooks { # [doc = " Provides a human-readable description of the node type."] fn descr () -> & 'static str ; }